     1→import React, { useState, useCallback, useEffect } from "react";
     2→import { useAuth } from "@/hooks/useAuth";
     3→import { supabase } from "@/integrations/supabase/client";
     4→import AppHeader from "@/components/AppHeader";
     5→import AuthDialog from "@/components/AuthDialog";
     6→import JobSidebar from "@/components/JobSidebar";
     7→import JobDetailView from "@/components/JobDetailView";
     8→import { SidebarProvider, SidebarTrigger, SidebarInset } from "@/components/ui/sidebar";
     9→import { toast } from "sonner";
    10→
    11→export interface PastJob {
    12→  id: string;
    13→  title: string | null;
    14→  job_description: string;
    15→  status: string;
    16→  created_at: string;
    17→  resume_count: number;
    18→  jd_analysis_json: any;
    19→  dynamic_weights_json: Record<string, number> | null;
    20→}
    21→
    22→export interface Result {
    23→  id: string;
    24→  resume_id: string;
    25→  overall_score: number;
    26→  missing_skills: string[];
    27→  red_flags: any;
    28→  summary: string | null;
    29→  interview_questions: any;
    30→  filename: string;
    31→  file_path: string | null;
    32→  candidate_name: string | null;
    33→  candidate_email?: string | null;
    34→  candidate_phone?: string | null;
    35→  candidate_location?: string | null;
    36→  // Dynamic scoring fields
    37→  hard_fit?: boolean;
    38→  category_scores_json?: Record<string, { score: number; evidence?: any[]; notes?: string }>;
    39→  confidence?: number;
    40→  strengths_json?: string[];
    41→  gaps_json?: string[];
    42→  explanation_json?: { summary?: string; why_ranked_here?: string; key_tradeoffs?: string };
    43→  matched_must_haves?: string[];
    44→  missing_must_haves?: string[];
    45→  scoring_version?: string;
    46→  pending?: boolean;
    47→}
    48→
    49→export interface ExistingResume {
    50→  id: string;
    51→  filename: string;
    52→  file_path: string | null;
    53→  candidate_name: string | null;
    54→  created_at: string;
    55→}
    56→
    57→const Index = () => {
    58→  const { user } = useAuth();
    59→
    60→  const [pastJobs, setPastJobs] = useState<PastJob[]>([]);
    61→  const [selectedJobId, setSelectedJobId] = useState<string | null>(null);
    62→  const [loadingPastJobs, setLoadingPastJobs] = useState(false);
    63→  const [results, setResults] = useState<Result[]>([]);
    64→  const [existingResumes, setExistingResumes] = useState<ExistingResume[]>([]);
    65→  const [authOpen, setAuthOpen] = useState(false);
    66→
    67→  const selectedJob = pastJobs.find((j) => j.id === selectedJobId) ?? null;
    68→
    69→  const fetchPastJobs = useCallback(async () => {
    70→    if (!user) return;
    71→    setLoadingPastJobs(true);
    72→    try {
    73→      const { data: jobs } = await supabase
    74→        .from("jobs")
    75→        .select("id, title, job_description, status, created_at, jd_analysis_json, dynamic_weights_json, resumes(count)")
    76→        .eq("user_id", user.id)
    77→        .order("created_at", { ascending: false })
    78→        .limit(50);
    79→      if (jobs) {
    80→        setPastJobs(jobs.map((j: any) => ({
    81→          id: j.id,
    82→          title: j.title,
    83→          job_description: j.job_description,
    84→          status: j.status,
    85→          created_at: j.created_at,
    86→          resume_count: j.resumes?.[0]?.count ?? 0,
    87→          jd_analysis_json: j.jd_analysis_json,
    88→          dynamic_weights_json: j.dynamic_weights_json,
    89→        })));
    90→      }
    91→    } catch (err) {
    92→      console.error("Failed to load past jobs:", err);
    93→    } finally {
    94→      setLoadingPastJobs(false);
    95→    }
    96→  }, [user]);
    97→
    98→  useEffect(() => {
    99→    fetchPastJobs();
   100→  }, [fetchPastJobs]);
   101→
   102→  const loadJobData = async (jobId: string) => {
   103→    setSelectedJobId(jobId);
   104→    try {
   105→      const [resumesRes, resumeListRes] = await Promise.all([
   106→        supabase
   107→          .from("resumes")
   108→          .select("id, filename, file_path, candidate_name, created_at")
   109→          .eq("job_id", jobId)
   110→          .order("created_at", { ascending: false }),
   111→        supabase
   112→          .from("resumes")
   113→          .select("id, filename, file_path, candidate_name, parsed_json")
   114→          .eq("job_id", jobId),
   115→      ]);
   116→
   117→      const resumes = resumesRes.data ?? [];
   118→      setExistingResumes(resumes);
   119→
   120→      const resumeData = (resumeListRes.data ?? []) as Array<{
   121→        id: string;
   122→        filename: string;
   123→        file_path: string | null;
   124→        candidate_name: string | null;
   125→        parsed_json?: any;
   126→      }>;
   127→      if (resumeData.length === 0) {
   128→        setResults([]);
   129→        return;
   130→      }
   131→
   132→      const resumeIds = resumeData.map((r) => r.id);
   133→      const { data: resultData } = await supabase
   134→        .from("results")
   135→        .select("id, resume_id, overall_score, missing_skills, red_flags, summary, interview_questions, hard_fit, category_scores_json, confidence, strengths_json, gaps_json, explanation_json, matched_must_haves, missing_must_haves, scoring_version")
   136→        .in("resume_id", resumeIds);
   137→
   138→      const resumeMap = new Map(resumeData.map((r) => [r.id, r]));
   139→      const merged: Result[] = (resultData ?? []).map((r: any) => {
   140→        const resume = resumeMap.get(r.resume_id);
   141→        const parsed = resume?.parsed_json as any;
   142→        return {
   143→          ...r,
   144→          overall_score: r.overall_score ?? 0,
   145→          missing_skills: r.missing_skills ?? [],
   146→          filename: resume?.filename ?? "Unknown",
   147→          file_path: resume?.file_path ?? null,
   148→          candidate_name: resume?.candidate_name ?? null,
   149→          candidate_email: parsed?.email ?? parsed?.contact?.email ?? null,
   150→          candidate_phone: parsed?.phone ?? parsed?.contact?.phone ?? null,
   151→          candidate_location: parsed?.location ?? parsed?.contact?.location ?? null,
   152→        };
   153→      });
   154→      merged.sort((a, b) => b.overall_score - a.overall_score);
   155→      setResults(merged);
   156→    } catch (err) {
   157→      console.error("Failed to load job data:", err);
   158→      toast.error("Failed to load job data");
   159→    }
   160→  };
   161→
   162→  const handleNewJob = () => {
   163→    setSelectedJobId(null);
   164→    setResults([]);
   165→    setExistingResumes([]);
   166→  };
   167→
   168→  const handleJobCreated = (job: PastJob) => {
   169→    setPastJobs((prev) => [job, ...prev]);
   170→    setSelectedJobId(job.id);
   171→    loadJobData(job.id);
   172→  };
   173→
   174→  const handleRenameJob = (jobId: string, newTitle: string) => {
   175→    setPastJobs((prev) =>
   176→      prev.map((j) => (j.id === jobId ? { ...j, title: newTitle } : j))
   177→    );
   178→  };
   179→
   180→  const handleDeleteJob = async (jobId: string) => {
   181→    try {
   182→      await supabase.from("resumes").delete().eq("job_id", jobId);
   183→      await supabase.from("jobs").delete().eq("id", jobId);
   184→      setPastJobs((prev) => prev.filter((j) => j.id !== jobId));
   185→      if (selectedJobId === jobId) handleNewJob();
   186→      toast.success("Job deleted");
   187→    } catch {
   188→      toast.error("Failed to delete job");
   189→    }
   190→  };
   191→
   192→  const handleJobUpdated = (jobId: string, updates: Partial<PastJob>) => {
   193→    setPastJobs((prev) =>
   194→      prev.map((j) => (j.id === jobId ? { ...j, ...updates } : j))
   195→    );
   196→  };
   197→
   198→  const requireAuth = useCallback(() => {
   199→    if (!user) { setAuthOpen(true); return true; }
   200→    return false;
   201→  }, [user]);
   202→
   203→  return (
   204→    <SidebarProvider className="h-svh overflow-hidden">
   205→      <JobSidebar
   206→        pastJobs={pastJobs}
   207→        selectedJobId={selectedJobId}
   208→        loadingPastJobs={loadingPastJobs}
   209→        onSelectJob={loadJobData}
   210→        onNewJob={handleNewJob}
   211→        onRenameJob={handleRenameJob}
   212→        onDeleteJob={handleDeleteJob}
   213→        onAuthRequired={() => setAuthOpen(true)}
   214→        isAuthenticated={!!user}
   215→      />
   216→
   217→      <SidebarInset className="h-svh overflow-y-auto">
   218→        <AppHeader />
   219→        <div className="flex items-center h-10 px-4 border-b border-border md:hidden">
   220→          <SidebarTrigger />
   221→          <span className="ml-2 text-sm font-medium text-muted-foreground">Job History</span>
   222→        </div>
   223→        <JobDetailView
   224→          selectedJobId={selectedJobId}
   225→          selectedJob={selectedJob}
   226→          results={results}
   227→          setResults={setResults}
   228→          existingResumes={existingResumes}
   229→          setExistingResumes={setExistingResumes}
   230→          onJobCreated={handleJobCreated}
   231→          onAuthRequired={() => setAuthOpen(true)}
   232→          isAuthenticated={!!user}
   233→          onJobUpdated={handleJobUpdated}
   234→        />
   235→      </SidebarInset>
   236→
   237→      <AuthDialog open={authOpen} onOpenChange={setAuthOpen} defaultTab="signin" />
   238→    </SidebarProvider>
   239→  );
   240→};
   241→
   242→export default Index;
   243→

