     1→import { useState, useCallback, useRef, useEffect } from "react";
     2→import { useAuth } from "@/hooks/useAuth";
     3→import { usePlatformConfig } from "@/hooks/usePlatformConfig";
     4→import { supabase } from "@/integrations/supabase/client";
     5→import { Button } from "@/components/ui/button";
     6→import { Textarea } from "@/components/ui/textarea";
     7→import { Checkbox } from "@/components/ui/checkbox";
     8→import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
     9→import { Badge } from "@/components/ui/badge";
    10→import { Table, TableBody, TableHead, TableHeader, TableRow } from "@/components/ui/table";
    11→import { Progress } from "@/components/ui/progress";
    12→import {
    13→  AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent,
    14→  AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle
    15→} from "@/components/ui/alert-dialog";
    16→import { toast } from "sonner";
    17→import {
    18→  Upload, Copy, Loader2, FileText,
    19→  AlertTriangle, X, Trash2, RefreshCw, CheckCircle2
    20→} from "lucide-react";
    21→import ScoreSummaryCards from "@/components/ScoreSummaryCards";
    22→import CandidateRow from "@/components/CandidateRow";
    23→import type { PastJob, Result, ExistingResume } from "@/pages/Index";
    24→
    25→interface JobDetailViewProps {
    26→  selectedJobId: string | null;
    27→  selectedJob: PastJob | null;
    28→  results: Result[];
    29→  setResults: (results: Result[] | ((prev: Result[]) => Result[])) => void;
    30→  existingResumes: ExistingResume[];
    31→  setExistingResumes: (resumes: ExistingResume[] | ((prev: ExistingResume[]) => ExistingResume[])) => void;
    32→  onJobCreated: (job: PastJob) => void;
    33→  onAuthRequired: () => void;
    34→  onJobUpdated?: (jobId: string, updates: Partial<PastJob>) => void;
    35→  isAuthenticated?: boolean;
    36→}
    37→
    38→interface UploadedFile {
    39→  file: File;
    40→  name: string;
    41→}
    42→
    43→const UUID_REGEX = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
    44→
    45→const JobDetailView = ({
    46→  selectedJobId,
    47→  selectedJob,
    48→  results,
    49→  setResults,
    50→  existingResumes,
    51→  setExistingResumes,
    52→  onJobCreated,
    53→  onAuthRequired,
    54→  onJobUpdated,
    55→  isAuthenticated = true,
    56→}: JobDetailViewProps) => {
    57→  const { user, profile, refreshProfile } = useAuth();
    58→  const { data: config } = usePlatformConfig();
    59→
    60→  const [jobDescription, setJobDescription] = useState("");
    61→  const [files, setFiles] = useState<UploadedFile[]>([]);
    62→  const [ranking, setRanking] = useState(false);
    63→  const [rankingProgress, setRankingProgress] = useState(0);
    64→  const [scoredCount, setScoredCount] = useState(0);
    65→  const [totalToScore, setTotalToScore] = useState(0);
    66→  const [expandedRows, setExpandedRows] = useState<Set<string>>(new Set());
    67→  const [dragOver, setDragOver] = useState(false);
    68→  const [rankingError, setRankingError] = useState<{ type: "credits" | "rate_limit" | "generic"; message: string } | null>(null);
    69→  const [validationErrors, setValidationErrors] = useState<string[]>([]);
    70→  const [selectedResumes, setSelectedResumes] = useState<Set<string>>(new Set());
    71→  const [deleteConfirm, setDeleteConfirm] = useState<{type: "single" | "bulk"; resumeId?: string; filePath?: string | null;} | null>(null);
    72→  const [deleting, setDeleting] = useState(false);
    73→  const [analyzingJd, setAnalyzingJd] = useState(false);
    74→  const [dismissedResumes, setDismissedResumes] = useState<Set<string>>(new Set());
    75→
    76→  const resultsRef = useRef<HTMLDivElement>(null);
    77→  const rankingFilesRef = useRef<Set<string>>(new Set());
    78→  const maxResumes = config?.max_resumes_per_job ?? 10;
    79→  const maxFileSizeMb = config?.max_file_size_mb ?? 5;
    80→
    81→  const isNewJobMode = selectedJobId === null;
    82→  const isExistingJob = selectedJobId !== null && selectedJob !== null;
    83→
    84→  const UUID_REGEX = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
    85→  const formatCandidateName = (filename: string) => {
    86→    const name = filename.replace(/\.\w+$/, "");
    87→    if (UUID_REGEX.test(name)) return `Candidate`;
    88→    return name.replace(/[-_]/g, " ").replace(/\b\w/g, (c) => c.toUpperCase());
    89→  };
    90→
    91→  // Merge unranked resumes
    92→  const resultResumeIds = new Set(results.map((r) => r.resume_id));
    93→  const pendingResumes: Result[] = existingResumes
    94→    .filter((r) => !resultResumeIds.has(r.id))
    95→    .map((r) => ({
    96→      id: `pending-${r.id}`,
    97→      resume_id: r.id,
    98→      overall_score: 0,
    99→      missing_skills: [], red_flags: {}, summary: null, interview_questions: null,
   100→      filename: r.filename, file_path: r.file_path, candidate_name: r.candidate_name,
   101→      pending: true,
   102→    }));
   103→  const allResults = [...results, ...pendingResumes];
   104→
   105→  // Selection helpers
   106→  const toggleSelectResume = (resumeId: string) => {
   107→    setSelectedResumes((prev) => {
   108→      const next = new Set(prev);
   109→      if (next.has(resumeId)) next.delete(resumeId); else next.add(resumeId);
   110→      return next;
   111→    });
   112→  };
   113→  const toggleSelectAll = () => {
   114→    if (selectedResumes.size === allResults.length) setSelectedResumes(new Set());
   115→    else setSelectedResumes(new Set(allResults.map((r) => r.resume_id)));
   116→  };
   117→
   118→  // Delete logic
   119→  const deleteResume = async (resumeId: string, filePath: string | null) => {
   120→    if (filePath) await supabase.storage.from("resumes").remove([filePath]);
   121→    await supabase.from("results").delete().eq("resume_id", resumeId);
   122→    await supabase.from("resumes").delete().eq("id", resumeId);
   123→    setResults((prev: Result[]) => prev.filter((r) => r.resume_id !== resumeId));
   124→    setExistingResumes((prev: ExistingResume[]) => prev.filter((r) => r.id !== resumeId));
   125→    setSelectedResumes((prev) => { const next = new Set(prev); next.delete(resumeId); return next; });
   126→  };
   127→
   128→  const handleDeleteConfirm = async () => {
   129→    if (!deleteConfirm) return;
   130→    setDeleting(true);
   131→    try {
   132→      if (deleteConfirm.type === "single" && deleteConfirm.resumeId) {
   133→        await deleteResume(deleteConfirm.resumeId, deleteConfirm.filePath ?? null);
   134→        toast.success("Resume deleted");
   135→      } else if (deleteConfirm.type === "bulk") {
   136→        const toDelete = allResults.filter((r) => selectedResumes.has(r.resume_id));
   137→        for (const r of toDelete) await deleteResume(r.resume_id, r.file_path);
   138→        toast.success(`${toDelete.length} resume(s) deleted`);
   139→      }
   140→    } catch { toast.error("Failed to delete"); }
   141→    finally { setDeleting(false); setDeleteConfirm(null); }
   142→  };
   143→
   144→  // File handling
   145→  const handleFileDrop = useCallback((e: React.DragEvent) => {
   146→    e.preventDefault(); setDragOver(false);
   147→    const dropped = Array.from(e.dataTransfer.files).filter(
   148→      (f) => f.type === "application/pdf" || f.type === "application/vnd.openxmlformats-officedocument.wordprocessingml.document"
   149→    );
   150→    addFiles(dropped);
   151→  }, [files, maxResumes, maxFileSizeMb]);
   152→
   153→  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
   154→    if (e.target.files) addFiles(Array.from(e.target.files));
   155→  };
   156→
   157→  const addFiles = (newFiles: File[]) => {
   158→    const currentCount = isExistingJob ? existingResumes.length + files.length : files.length;
   159→    const valid = newFiles.filter((f) => {
   160→      if (f.size > maxFileSizeMb * 1024 * 1024) { toast.error(`${f.name} exceeds ${maxFileSizeMb}MB limit`); return false; }
   161→      return true;
   162→    });
   163→    const remaining = maxResumes - currentCount;
