   389→        setScoredCount(done);
   390→        const pct = resumeIds.length > 0 ? Math.round((done / resumeIds.length) * 35) : 0;
   391→        setRankingProgress(Math.min(60 + pct, 95));
   392→      }
   393→
   394→      const { data: jobData } = await supabase.from("jobs").select("status").eq("id", jobId).single();
   395→      if (jobData?.status === "completed") {
   396→         const { data: allResumes } = await supabase.from("resumes").select("id, filename, file_path, candidate_name, parsed_json").eq("job_id", jobId);
   397→         if (allResumes) {
   398→           const allResumeIds = allResumes.map((r: any) => r.id);
   399→            const { data: resultData } = await supabase
   400→              .from("results")
