   402→              .in("resume_id", allResumeIds);
   403→
   404→            const resumeMap = new Map(allResumes.map((r: any) => [r.id, r]));
   405→            const merged: Result[] = (resultData ?? []).map((r: any) => {
   406→              const resume = resumeMap.get(r.resume_id);
   407→              const parsed = resume?.parsed_json as any;
   408→              return {
   409→                ...r,
   410→                overall_score: r.overall_score ?? 0,
   411→                missing_skills: r.missing_skills ?? [],
   412→                filename: resume?.filename ?? "Unknown",
   413→                file_path: resume?.file_path ?? null,
   414→                candidate_name: resume?.candidate_name ?? null,
   415→                candidate_email: parsed?.email ?? parsed?.contact?.email ?? null,
   416→                candidate_phone: parsed?.phone ?? parsed?.contact?.phone ?? null,
   417→                candidate_location: parsed?.location ?? parsed?.contact?.location ?? null,
   418→              };
   419→            });
   420→          merged.sort((a, b) => b.overall_score - a.overall_score);
   421→          setResults(merged);
   422→        }
   423→        setRankingProgress(100);
   424→        await refreshProfile();
   425→        setTimeout(() => { resultsRef.current?.scrollIntoView({ behavior: "smooth", block: "start" }); }, 200);
   426→        return;
   427→      }
   428→      if (jobData?.status === "failed") throw new Error("Ranking failed on server");
   429→    }
   430→    throw new Error("Ranking timed out");
   431→  };
