   153→      .eq("user_id", user.id)
   154→      .gte("created_at", oneMinAgo);
   155→    if ((count ?? 0) > 3) {
   156→      return new Response(JSON.stringify({ error: "Rate limit: max 3 jobs per minute" }), {
   157→        status: 429, headers: { ...corsHeaders, "Content-Type": "application/json" },
   158→      });
   159→    }
   160→
   161→    // Fetch job with JD analysis
