   179→    if (!targetResumeIds.length) {
   180→      const { data: allResumes } = await supabase
   181→        .from("resumes")
   182→        .select("id")
   183→        .eq("job_id", job_id);
   184→      targetResumeIds = (allResumes || []).map((r: any) => r.id);
   185→    }
   186→
   187→    if (targetResumeIds.length === 0) {
   188→      return new Response(JSON.stringify({ error: "No resumes to rank" }), {
   189→        status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" },
   190→      });
   191→    }
   192→
   193→    // Deduct credits (charge for min of resume count and 20)
   194→    const creditsToCharge = Math.min(targetResumeIds.length, 20);
