   772→// ── PDF text extraction fallback ───────────────────────────────
   773→function extractPdfText(bytes: Uint8Array): string {
   774→  const raw = new TextDecoder("latin1").decode(bytes);
   775→  const textChunks: string[] = [];
   776→  const btEtRegex = /BT\s([\s\S]*?)ET/g;
   777→  let block;
   778→  while ((block = btEtRegex.exec(raw)) !== null) {
   779→    const parenRegex = /\(([^)]*)\)/g;
   780→    let match;
   781→    while ((match = parenRegex.exec(block[1])) !== null) {
   782→      const decoded = match[1]
   783→        .replace(/\\n/g, "\n").replace(/\\r/g, "\r").replace(/\\t/g, "\t")
   784→        .replace(/\\\\/g, "\\").replace(/\\\(/g, "(").replace(/\\\)/g, ")");
   785→      if (decoded.trim()) textChunks.push(decoded);
   786→    }
   787→  }
   788→  if (textChunks.join(" ").trim().length < 200) {
   789→    const streamRegex = /stream\r?\n([\s\S]*?)\r?\nendstream/g;
   790→    let sm;
   791→    while ((sm = streamRegex.exec(raw)) !== null) {
   792→      const readable = sm[1].replace(/[^\x20-\x7E\n\r\t]/g, " ").replace(/\s+/g, " ").trim();
   793→      if (readable.length > 50) textChunks.push(readable);
   794→    }
   795→  }
   796→  return textChunks.join(" ").replace(/\s+/g, " ").trim().slice(0, 10000);
   797→}
